import random
import logging
from locust import HttpUser, task, between, events

# 配置日志，确保秒杀失败日志能清晰输出
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("seckill_log")

# 订阅 Locust 事件，在控制台实时打印失败日志
@events.request.add_listener
def log_seckill_failure(request_type, name, response_time, response_length, response, context, exception):
    if exception:
        logger.error(f"请求失败: {name} | 异常: {exception}")
    elif name == "/api/seckill/start" and response.status_code != 200:
        logger.error(f"秒杀HTTP失败: 状态码 {response.status_code} | 响应: {response.text}")

class SeckillUser(HttpUser):
    # 要求3：Think Time 1-3秒随机
    wait_time = between(1, 3)

    # 默认主机地址，运行时可通过 --host 参数覆盖
    host = "http://localhost:8080"

    def on_start(self):
        """
        用户初始化逻辑：每个虚拟用户启动时先执行一次登录，
        确保后续流程有Token可用，避免未登录状态下的无效请求。
        """
        self.token = ""
        self.headers = {}
        self.product_ids = ["1001", "1002", "1003"] # 默认商品ID兜底
        self.login()

    def login(self):
        """要求4：登录成功后保存token"""
        # 使用 Locust 分配的用户唯一ID模拟不同用户账号
        payload = {
            "username": f"test_user_{self.id}",
            "password": "password123"
        }

        with self.client.post("/api/auth/login", json=payload, catch_response=True, name="/api/auth/login") as response:
            if response.status_code == 200:
                try:
                    data = response.json()
                    # 假设接口返回格式为 {"code": 0, "data": {"token": "xxx"}}
                    if data.get("code") == 0 and data.get("data").get("token"):
                        self.token = data["data"]["token"]
                        self.headers = {"Authorization": f"Bearer {self.token}"}
                        response.success()
                    else:
                        response.failure(f"登录业务逻辑失败: {data.get('msg')}")
                except Exception as e:
                    response.failure(f"解析登录响应失败: {e}")
            else:
                response.failure(f"登录HTTP失败: 状态码 {response.status_code}")

    @task(10)
    def browse_products(self):
        """浏览商品列表"""
        if not self.token:
            return # 未登录则跳过

        with self.client.get("/api/products", headers=self.headers, catch_response=True, name="/api/products") as response:
            if response.status_code == 200:
                try:
                    data = response.json()
                    # 假设返回 {"code": 0, "data": [{"id": "888"}, ...]}
                    if data.get("code") == 0 and isinstance(data.get("data"), list):
                        # 动态提取商品ID，供后续查看详情和秒杀使用
                        extracted_ids = [item["id"] for item in data["data"] if "id" in item]
                        if extracted_ids:
                            self.product_ids = extracted_ids
                        response.success()
                    else:
                        response.failure("获取商品列表业务失败")
                except Exception as e:
                    response.failure(f"解析商品列表响应失败: {e}")
            else:
                response.failure(f"获取商品列表HTTP失败: 状态码 {response.status_code}")

    @task(8)
    def view_product_detail(self):
        """查看商品详情"""
        if not self.token or not self.product_ids:
            return

        # 随机选择一个商品查看详情
        product_id = random.choice(self.product_ids)
        # 使用 name 参数将动态URL在Locust统计面板中聚合展示
        self.client.get(
            f"/api/products/{product_id}", 
            headers=self.headers, 
            name="/api/products/{id}"
        )

    @task(2)
    def seckill(self):
        """参与秒杀"""
        if not self.token or not self.product_ids:
            return

        product_id = random.choice(self.product_ids)
        payload = {"productId": product_id}

        with self.client.post("/api/seckill/start", json=payload, headers=self.headers, catch_response=True, name="/api/seckill/start") as response:
            # 要求5：秒杀失败时记录日志
            if response.status_code == 200:
                try:
                    data = response.json()
                    # 假设秒杀成功返回 {"code": 0}, 失败返回 {"code": -1, "msg": "已售罄"}
                    if data.get("code") == 0:
                        response.success()
                    else:
                        # 业务层面的秒杀失败（如售罄、资格不足等），标记为失败并记录日志
                        fail_msg = data.get('msg', '未知业务错误')
                        logger.warning(f"用户 {self.id} 秒杀商品 {product_id} 失败: {fail_msg}")
                        response.failure(fail_msg)
                except Exception as e:
                    logger.error(f"解析秒杀响应失败: {e}")
                    response.failure(f"解析秒杀响应失败: {e}")
            else:
                # HTTP层面的失败（如500、502等），已在上方全局事件监听中记录日志
                response.failure(f"秒杀HTTP异常: 状态码 {response.status_code}")

    @task(3)
    def query_orders(self):
        """查询订单"""
        if not self.token:
            return

        self.client.get("/api/orders", headers=self.headers, name="/api/orders")
```

### 脚本设计亮点说明：

1. **动态数据关联**：在 `browse_products` 中动态提取商品列表的 `id`，存入 `self.product_ids`，供后续的 `view_product_detail` 和 `seckill` 随机取用，真实模拟用户“浏览->选中->秒杀”的链路。
2. **URL 聚合统计**：对于动态路径 `/api/products/{id}`，使用了 `name="/api/products/{id}"` 参数。这样在 Locust 的 Web UI 中，不会因为成百上千个不同的商品 ID 而撑爆统计表格，它们会被归类到同一个分组下进行 RPS/响应时间统计。
3. **双重失败日志记录**：
   - **业务级失败**（HTTP 200 但业务返回售罄/失败）：在 `seckill` 方法内通过 `logger.warning` 记录，并调用 `response.failure()` 让 Locust 统计其为失败请求。
   - **网络/服务级失败**（HTTP 500/502/超时等）：通过 `@events.request.add_listener` 全局监听，自动捕获并使用 `logger.error` 打印，避免代码冗余。
4. **前置登录保障**：虽然登录是权重5的任务，但为了避免用户一开始处于未登录态导致前几个任务全部空转，在 `on_start` 中强制执行了一次登录。后续运行中的 `login` 任务（权重5）可模拟用户 Token 过期后的重新登录行为。

